INSERT INTO safari_packages (id, category_id, title, slug, featured_image, short_desc, full_desc, duration, price, currency, location, highlights, inclusions, exclusions, itinerary, is_featured, is_published, published_at, meta_title, meta_description, meta_keywords, views_count, enquiries_count, featured_until, created_at, updated_at, deleted_at) VALUES ('1', '2', '7-Day Masai Mara Safari', '7-day-masai-mara-safari', 'packages/xrANpBWUZ8hDNi5YmOjYi0YHjAk22hpQgWiYH0o2.jpg', 'Experience the magic of the Masai Mara with this 7-day safari adventure.', 'Experience the magic of the Masai Mara with our comprehensive 7-day safari adventure. This package includes game drives, cultural visits, and comfortable accommodation.', '7', '2500', 'USD', 'Masai Mara, Kenya', '["Game drives in Masai Mara","Hot air balloon ride","Visit to Maasai village","Luxury accommodation"]', '["Accommodation for 6 nights","All meals","Transport in 4x4 safari vehicle","Professional guide"]', '["International flights","Travel insurance","Personal expenses"]', NULL, '1', '1', '2026-06-15 13:56:25', '7-Day Masai Mara Safari - Best Safari Experience', 'Experience the best of Masai Mara with our 7-day safari package.', NULL, '1253', '46', NULL, '2026-06-15 13:56:25', '2026-06-17 14:43:51', NULL);
