-- Table: migrations
CREATE TABLE "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);


-- Table: sqlite_sequence
CREATE TABLE sqlite_sequence(name,seq);


-- Table: users
CREATE TABLE "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "phone" varchar, "country" varchar, "avatar" varchar, "remember_token" varchar, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, "deleted_at" datetime);


-- Table: password_reset_tokens
CREATE TABLE "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));

-- Table: sessions
CREATE TABLE "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));


-- Table: roles
CREATE TABLE "roles" ("id" integer primary key autoincrement not null, "name" varchar not null, "guard_name" varchar not null default 'web', "created_at" datetime, "updated_at" datetime);


-- Table: permissions
CREATE TABLE "permissions" ("id" integer primary key autoincrement not null, "name" varchar not null, "guard_name" varchar not null default 'web', "created_at" datetime, "updated_at" datetime);


-- Table: model_has_permissions
CREATE TABLE "model_has_permissions" ("permission_id" integer not null, "model_type" varchar not null, "model_id" integer not null, foreign key("permission_id") references "permissions"("id") on delete cascade, primary key ("permission_id", "model_id", "model_type"));

-- Table: model_has_roles
CREATE TABLE "model_has_roles" ("role_id" integer not null, "model_type" varchar not null, "model_id" integer not null, foreign key("role_id") references "roles"("id") on delete cascade, primary key ("role_id", "model_id", "model_type"));


-- Table: role_has_permissions
CREATE TABLE "role_has_permissions" ("permission_id" integer not null, "role_id" integer not null, foreign key("permission_id") references "permissions"("id") on delete cascade, foreign key("role_id") references "roles"("id") on delete cascade, primary key ("permission_id", "role_id"));


-- Table: package_categories
CREATE TABLE "package_categories" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "description" text, "icon" varchar, "is_active" tinyint(1) not null default '1', "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime);


-- Table: safari_packages
CREATE TABLE "safari_packages" ("id" integer primary key autoincrement not null, "category_id" integer, "title" varchar not null, "slug" varchar not null, "featured_image" varchar, "short_desc" varchar not null, "full_desc" text, "duration" integer, "price" numeric, "currency" varchar not null default 'USD', "location" varchar, "highlights" text, "inclusions" text, "exclusions" text, "itinerary" text, "is_featured" tinyint(1) not null default '0', "is_published" tinyint(1) not null default '0', "published_at" datetime, "meta_title" varchar, "meta_description" text, "meta_keywords" varchar, "views_count" integer not null default '0', "enquiries_count" integer not null default '0', "featured_until" datetime, "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, foreign key("category_id") references "package_categories"("id") on delete set null);


-- Table: destinations
CREATE TABLE "destinations" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "description" text, "featured_image" varchar, "country" varchar, "region" varchar, "latitude" numeric, "longitude" numeric, "best_time_to_visit" varchar, "wildlife" text, "activities" text, "gallery" text, "is_featured" tinyint(1) not null default '0', "status" varchar check ("status" in ('active', 'inactive', 'archived')) not null default 'active', "meta_title" varchar, "meta_description" text, "views_count" integer not null default '0', "created_at" datetime, "updated_at" datetime);


-- Table: package_destination
CREATE TABLE "package_destination" ("package_id" integer not null, "destination_id" integer not null, "display_order" integer not null default '0', foreign key("package_id") references "safari_packages"("id") on delete cascade, foreign key("destination_id") references "destinations"("id") on delete cascade, primary key ("package_id", "destination_id"));


-- Table: enquiries
CREATE TABLE "enquiries" ("id" integer primary key autoincrement not null, "user_id" integer, "assigned_to" integer, "package_id" integer, "full_name" varchar not null, "email" varchar not null, "phone" varchar not null, "country" varchar not null, "adults" integer not null default '1', "children" integer not null default '0', "travel_date" date, "duration" integer, "budget" varchar, "message" text, "status" varchar check ("status" in ('new', 'contacted', 'quotation_sent', 'negotiation', 'confirmed', 'cancelled')) not null default 'new', "last_contacted_at" datetime, "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, foreign key("user_id") references "users"("id") on delete set null, foreign key("assigned_to") references "users"("id") on delete set null, foreign key("package_id") references "safari_packages"("id") on delete set null);


-- Table: enquiry_notes
CREATE TABLE "enquiry_notes" ("id" integer primary key autoincrement not null, "enquiry_id" integer not null, "user_id" integer not null, "note" text not null, "is_internal" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("enquiry_id") references "enquiries"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);


-- Table: follow_up_reminders
CREATE TABLE "follow_up_reminders" ("id" integer primary key autoincrement not null, "enquiry_id" integer not null, "reminder_date" date not null, "reminder_time" time, "notes" text, "status" varchar check ("status" in ('pending', 'sent', 'completed', 'cancelled')) not null default 'pending', "completed" tinyint(1) not null default '0', "completed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("enquiry_id") references "enquiries"("id") on delete cascade);


-- Table: enquiry_status_history
CREATE TABLE "enquiry_status_history" ("id" integer primary key autoincrement not null, "enquiry_id" integer not null, "status" varchar not null, "changed_by" integer, "notes" text, "changed_at" datetime not null, foreign key("changed_by") references users("id") on delete cascade on update no action, foreign key("enquiry_id") references enquiries("id") on delete cascade on update no action);


-- Table: __temp__enquiry_status_history
CREATE TABLE "__temp__enquiry_status_history" ("id" integer primary key autoincrement not null, "enquiry_id" integer not null, "status" varchar not null, "changed_by" integer not null, "notes" text, "changed_at" datetime not null, foreign key("enquiry_id") references enquiries("id") on delete cascade on update no action, foreign key("changed_by") references users("id") on delete cascade on update no action);

